<script setup lang="ts">definePageMeta({layout:false,middleware:'auth'});const route=useRoute(),{api}=useShopApi();const{data}=await useAsyncData(`invoice-${route.params.id}`,()=>api<any>(`/profile/orders/${route.params.id}/invoice`));useHead({title:'فاکتور سفارش',htmlAttrs:{lang:'fa',dir:'rtl'}});const money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v)</script>
<template><main v-if="data" class="min-h-screen bg-slate-100 p-4 text-slate-900 print:bg-white print:p-0"><div class="mx-auto max-w-4xl rounded-2xl bg-white p-6 shadow-sm print:max-w-none print:rounded-none print:p-4 print:shadow-none"><header class="flex items-start justify-between border-b pb-6"><div><h1 class="text-2xl font-black">{{data.settings.site_title||'فروشگاه'}}</h1><p class="mt-2 text-sm text-slate-500">فاکتور فروش کالا</p></div><div class="text-left text-sm"><p>شماره: <b dir="ltr">{{data.order.number}}</b></p><p class="mt-2">تاریخ: {{new Date(data.order.created_at).toLocaleDateString('fa-IR')}}</p></div></header><section class="mt-6 grid gap-4 rounded-xl bg-slate-50 p-4 text-sm sm:grid-cols-2"><div><b>خریدار</b><p class="mt-2">{{data.order.user?.name||data.order.address_snapshot.receiver_name}}</p><p>{{data.order.user?.mobile}}</p></div><div><b>نشانی تحویل</b><p class="mt-2 leading-7">{{data.order.address_snapshot.province}}، {{data.order.address_snapshot.city}}، {{data.order.address_snapshot.address}}</p><p>کد پستی: {{data.order.address_snapshot.postal_code}}</p></div></section><div class="mt-6 overflow-x-auto"><table class="w-full min-w-[650px] border-collapse text-right text-sm"><thead class="bg-slate-900 text-white"><tr><th class="p-3">ردیف</th><th class="p-3">شرح کالا</th><th class="p-3">تعداد</th><th class="p-3">مبلغ واحد</th><th class="p-3">مبلغ کل</th></tr></thead><tbody><tr v-for="(item,i) in data.order.items" :key="item.id" class="border-b"><td class="p-3">{{i+1}}</td><td class="p-3"><b>{{item.title}}</b><p class="mt-1 text-xs text-slate-400">{{item.sku}} • {{Object.values(item.attributes||{}).join(' / ')}}</p></td><td class="p-3">{{item.quantity}}</td><td class="p-3">{{money(item.unit_price)}}</td><td class="p-3 font-bold">{{money(item.total)}}</td></tr></tbody></table></div><section class="mr-auto mt-6 max-w-sm space-y-3 text-sm"><div class="flex justify-between"><span>جمع کالاها</span><span>{{money(data.order.subtotal)}} تومان</span></div><div class="flex justify-between text-emerald-700"><span>تخفیف</span><span>− {{money(data.order.discount_amount)}} تومان</span></div><div class="flex justify-between"><span>هزینه ارسال</span><span>{{money(data.order.shipping_amount)}} تومان</span></div><div class="flex justify-between border-t pt-3 text-lg font-black"><span>مبلغ نهایی</span><span>{{money(data.order.payable_amount)}} تومان</span></div></section><footer class="mt-10 border-t pt-5 text-xs leading-6 text-slate-400"><p>{{data.settings.site_title}} — این فاکتور به‌صورت الکترونیکی صادر شده است.</p><p v-if="data.settings.contact_us">{{data.settings.contact_us}}</p></footer><div class="mt-6 flex justify-center gap-3 print:hidden"><button class="rounded-xl bg-brand-700 px-6 py-3 font-bold text-white" @click="window.print()">چاپ فاکتور</button><NuxtLink :to="`/profile/orders/${data.order.id}`" class="rounded-xl border px-6 py-3 font-bold">بازگشت به سفارش</NuxtLink></div></div></main></template>
